blocks.x:
worker_processes 1;
error_log /tmp/nginx-error.log warn;
pid /tmp/nginx.pid;
events {
worker_connections 512;
}
rtmp {
server {
listen 1935;
chunk_size 4096;
application ps5 {
live on;
record off;
sync 10ms;
# Notify our app when a stream starts
on_publish http://127.0.0.1:9988/on_publish;
}
}
}
http {
server {
listen 8080;
location /stat {
rtmp_stat all;
}
}
}
